-- ============================================================================
-- Event trust workflow
-- ============================================================================
--
-- Adds the missing operational layer around the existing multi-source model:
-- private audit notes for admin reconciliation, plus a public aggregate metrics
-- view for the "How Cebby verifies events" page.
-- ============================================================================

CREATE TABLE IF NOT EXISTS "public"."event_audit_logs" (
    "id"           bigint       NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "event_id"     bigint
        REFERENCES "public"."events"("id")
        ON UPDATE CASCADE ON DELETE SET NULL,
    "action"       text         NOT NULL,
    "summary"      text,
    "actor"        text         NOT NULL DEFAULT 'admin',
    "before_state" jsonb,
    "after_state"  jsonb,
    "metadata"     jsonb,
    "created_at"   timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY ("id")
);

COMMENT ON TABLE "public"."event_audit_logs" IS
    'Private operator audit trail for event reconciliation: merges, canonical source changes, visibility changes, and organizer edits.';
COMMENT ON COLUMN "public"."event_audit_logs"."action" IS
    'Machine-readable action key, e.g. event_merged, canonical_source_changed, status_changed, organizer_removed.';
COMMENT ON COLUMN "public"."event_audit_logs"."before_state" IS
    'Small JSON snapshot before the admin action. Store only operational fields, not raw scrape payloads.';
COMMENT ON COLUMN "public"."event_audit_logs"."after_state" IS
    'Small JSON snapshot after the admin action. Store only operational fields, not raw scrape payloads.';

CREATE INDEX IF NOT EXISTS "event_audit_logs_event_created_idx"
    ON "public"."event_audit_logs" ("event_id", "created_at" DESC);

CREATE INDEX IF NOT EXISTS "event_audit_logs_action_created_idx"
    ON "public"."event_audit_logs" ("action", "created_at" DESC);

REVOKE ALL ON "public"."event_audit_logs" FROM "anon", "authenticated";
GRANT ALL ON "public"."event_audit_logs" TO "postgres", "service_role";
GRANT USAGE, SELECT ON SEQUENCE "public"."event_audit_logs_id_seq" TO "postgres", "service_role";

CREATE OR REPLACE VIEW "public"."event_reliability_metrics" AS
WITH upcoming AS (
    SELECT e.id
    FROM "public"."events" e
    WHERE e.status = 'published'
      AND e.start_time >= now()
),
source_event_ids AS (
    SELECT DISTINCT esl.event_id
    FROM "public"."event_source_links" esl
    WHERE esl.url IS NOT NULL OR esl.source IS NOT NULL
),
multi_source_event_ids AS (
    SELECT esl.event_id
    FROM "public"."event_source_links" esl
    GROUP BY esl.event_id
    HAVING count(*) > 1
),
latest_checks AS (
    SELECT esl.event_id, max(esl.scraped_at) AS last_checked_at
    FROM "public"."event_source_links" esl
    GROUP BY esl.event_id
),
partner_peer_orgs AS (
    SELECT DISTINCT a.organization_id
    FROM "public"."accounts" a
    WHERE a.organization_id IS NOT NULL
      AND a.ingest_kind = 'partnership'
),
partner_event_ids AS (
    SELECT DISTINCT eo.event_id
    FROM "public"."event_organizers" eo
    JOIN "public"."accounts" a ON a.account_id = eo.account_id
    LEFT JOIN "public"."organizations" o ON o.id = a.organization_id
    LEFT JOIN partner_peer_orgs ppo ON ppo.organization_id = a.organization_id
    WHERE a.ingest_kind = 'partnership'
       OR o.verified_at IS NOT NULL
       OR ppo.organization_id IS NOT NULL
),
trusted_peer_orgs AS (
    SELECT DISTINCT a.organization_id
    FROM "public"."accounts" a
    WHERE a.organization_id IS NOT NULL
      AND a.is_verified = true
),
trusted_event_ids AS (
    SELECT DISTINCT eo.event_id
    FROM "public"."event_organizers" eo
    JOIN "public"."accounts" a ON a.account_id = eo.account_id
    LEFT JOIN trusted_peer_orgs tpo ON tpo.organization_id = a.organization_id
    WHERE a.is_verified = true
       OR tpo.organization_id IS NOT NULL
    EXCEPT
    SELECT event_id FROM partner_event_ids
),
counts AS (
    SELECT
        (SELECT count(*) FROM upcoming)::int AS total_upcoming_events,
        (SELECT count(*) FROM upcoming u JOIN source_event_ids s ON s.event_id = u.id)::int AS sourced_upcoming_events,
        (SELECT count(*) FROM upcoming u JOIN multi_source_event_ids s ON s.event_id = u.id)::int AS multi_source_upcoming_events,
        (SELECT count(*) FROM upcoming u JOIN partner_event_ids p ON p.event_id = u.id)::int AS partner_upcoming_events,
        (SELECT count(*) FROM upcoming u JOIN trusted_event_ids t ON t.event_id = u.id)::int AS trusted_organizer_upcoming_events,
        (SELECT count(*) FROM upcoming u JOIN latest_checks c ON c.event_id = u.id WHERE c.last_checked_at >= now() - interval '24 hours')::int AS checked_24h_upcoming_events,
        (SELECT count(*) FROM upcoming u LEFT JOIN source_event_ids s ON s.event_id = u.id WHERE s.event_id IS NULL)::int AS no_source_upcoming_events,
        (SELECT max(c.last_checked_at) FROM upcoming u JOIN latest_checks c ON c.event_id = u.id) AS latest_checked_at
)
SELECT
    now() AS generated_at,
    total_upcoming_events,
    sourced_upcoming_events,
    multi_source_upcoming_events,
    partner_upcoming_events,
    trusted_organizer_upcoming_events,
    checked_24h_upcoming_events,
    no_source_upcoming_events,
    latest_checked_at,
    CASE WHEN total_upcoming_events = 0 THEN 100::numeric
         ELSE round(sourced_upcoming_events * 100.0 / total_upcoming_events, 1)
    END AS sourced_percent,
    CASE WHEN total_upcoming_events = 0 THEN 0::numeric
         ELSE round(multi_source_upcoming_events * 100.0 / total_upcoming_events, 1)
    END AS multi_source_percent,
    CASE WHEN total_upcoming_events = 0 THEN 0::numeric
         ELSE round(partner_upcoming_events * 100.0 / total_upcoming_events, 1)
    END AS partner_percent,
    CASE WHEN total_upcoming_events = 0 THEN 0::numeric
         ELSE round(trusted_organizer_upcoming_events * 100.0 / total_upcoming_events, 1)
    END AS trusted_organizer_percent,
    CASE WHEN total_upcoming_events = 0 THEN 100::numeric
         ELSE round(checked_24h_upcoming_events * 100.0 / total_upcoming_events, 1)
    END AS checked_24h_percent
FROM counts;

COMMENT ON VIEW "public"."event_reliability_metrics" IS
    'Public aggregate health metrics for Cebby event trust. No raw payloads or private admin actions exposed.';

GRANT SELECT ON "public"."event_reliability_metrics" TO "anon", "authenticated", "service_role";
